// Runs the app's own Vite config behind an Amp portal. Generated by Amplify (https://github.com/springloadedco/amplify).
//
// Loads vite.config.* from the repository root unchanged, then serves it under /__vite/ on the
// portal's origin, where .amp/orb-proxy.mjs forwards it, with its HMR websocket over wss on 443.
// laravel-vite-plugin writes that origin to public/hot, so @vite tags point at the portal.

// Starter kits use Vite+ (`vp dev`), which wraps Vite; other apps use Vite directly. The specifier
// is a variable so Vite's config bundler does not try to resolve vite-plus in plain-Vite apps.
const load = (name) => import(name)
const plus = await load('vite-plus').catch(() => null)
const { loadConfigFromFile, mergeConfig, version } = plus ?? (await load('vite'))
// Vite 8 and Vite+ take HMR options as `server.ws`; older Vite (Laravel 11 ships 6) as `server.hmr`.
const hmrKey = plus || Number(version.split('.')[0]) >= 8 ? 'ws' : 'hmr'

export default async (env) => {
	const loaded = await loadConfigFromFile(env, undefined, process.cwd())
	const host = new URL(process.env.APP_URL).host

	// Echo connects to Reverb through the same portal origin.
	Object.assign(process.env, { VITE_REVERB_HOST: host, VITE_REVERB_PORT: '443', VITE_REVERB_SCHEME: 'https' })

	return mergeConfig(loaded?.config ?? {}, {
		base: '/__vite/',
		plugins: [inertiaSsrUnderBase],
		server: {
			host: '127.0.0.1',
			port: Number(process.env.AMPLIFY_VITE_PORT), // from .amp/orb.env
			strictPort: true,
			origin: `https://${host}`,
			allowedHosts: [host],
			cors: { origin: `https://${host}` },
			[hmrKey]: { protocol: 'wss', host, clientPort: 443 },
		},
	})
}

// Inertia renders pages in dev by posting to `<public/hot>/__inertia_ssr`, which the base above
// turns into /__vite/__inertia_ssr. Its Vite plugin listens at /__inertia_ssr, so map it back.
const inertiaSsrUnderBase = {
	name: 'amplify:inertia-ssr-under-base',
	enforce: 'pre',
	configureServer(server) {
		server.middlewares.use((request, _response, next) => {
			if (request.url.startsWith('/__vite/__inertia_ssr')) request.url = request.url.slice('/__vite'.length)
			next()
		})
	},
}
